
 CREATE TABLE IF NOT EXISTS slack_binding(id INTEGER PRIMARY KEY CHECK(id=1),team TEXT NOT NULL,app TEXT NOT NULL,bot TEXT NOT NULL,agent TEXT NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_inbox(event TEXT PRIMARY KEY,channel TEXT NOT NULL,sender TEXT NOT NULL,ts TEXT NOT NULL,root TEXT NOT NULL,text TEXT NOT NULL,thread TEXT NOT NULL,turn TEXT NOT NULL UNIQUE,status TEXT NOT NULL DEFAULT 'queued',checked INTEGER NOT NULL DEFAULT 0,UNIQUE(channel,ts)) STRICT;
 CREATE TABLE IF NOT EXISTS slack_closed_threads(id TEXT PRIMARY KEY) STRICT;
 CREATE TABLE IF NOT EXISTS slack_questions(id TEXT PRIMARY KEY,channel TEXT NOT NULL,sender TEXT NOT NULL,root TEXT NOT NULL,thread TEXT NOT NULL,turn TEXT NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_question_choices(id TEXT PRIMARY KEY,choices TEXT NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_question_callbacks(question TEXT PRIMARY KEY,id TEXT NOT NULL UNIQUE,answer TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued') STRICT;
 CREATE TABLE IF NOT EXISTS slack_media(turn TEXT NOT NULL,position INTEGER NOT NULL,remote TEXT NOT NULL,upload TEXT NOT NULL UNIQUE,name TEXT,bytes BLOB,PRIMARY KEY(turn,position)) STRICT;
 CREATE TABLE IF NOT EXISTS slack_document_workflows(id TEXT PRIMARY KEY,run TEXT NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_documents(id TEXT PRIMARY KEY,turn TEXT NOT NULL,thread TEXT NOT NULL,file TEXT NOT NULL,name TEXT NOT NULL,bytes BLOB NOT NULL,stage INTEGER NOT NULL DEFAULT 0,remote TEXT,url TEXT,UNIQUE(turn,file)) STRICT;
 CREATE TABLE IF NOT EXISTS slack_workflows(run TEXT PRIMARY KEY,channel TEXT NOT NULL,sender TEXT NOT NULL,root TEXT NOT NULL,workflow TEXT NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_approvals(run TEXT NOT NULL,revision INTEGER NOT NULL,notice TEXT NOT NULL UNIQUE,PRIMARY KEY(run,revision)) STRICT;
 CREATE TABLE IF NOT EXISTS slack_callbacks(notice TEXT PRIMARY KEY,id TEXT NOT NULL UNIQUE,accepted INTEGER NOT NULL CHECK(accepted IN (0,1)),status TEXT NOT NULL DEFAULT 'queued') STRICT;
 CREATE TABLE IF NOT EXISTS slack_workflow_cancels(id TEXT PRIMARY KEY,run TEXT NOT NULL,revision INTEGER NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_outbox(id TEXT PRIMARY KEY,channel TEXT NOT NULL,sender TEXT NOT NULL,root TEXT NOT NULL,text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',part INTEGER NOT NULL DEFAULT 0,timestamps TEXT NOT NULL DEFAULT '[]') STRICT;
 CREATE TABLE IF NOT EXISTS slack_recoveries(reply TEXT NOT NULL,revision INTEGER NOT NULL,action TEXT NOT NULL,status TEXT NOT NULL,part INTEGER NOT NULL,created TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(reply,revision)) STRICT;
 CREATE TABLE IF NOT EXISTS slack_delivery_cooldown(id INTEGER PRIMARY KEY CHECK(id=1),until INTEGER NOT NULL) STRICT;
 CREATE TABLE IF NOT EXISTS slack_session_cooldowns(method TEXT PRIMARY KEY,until INTEGER NOT NULL) STRICT;
 UPDATE slack_outbox SET status='uncertain' WHERE status='sending';
